package com.snovasys.ledgerline.dto;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * Report generated by verifying the double-entry global balance conservation.
 * sum(debits) - sum(credits) == 0.
 */
public class LedgerIntegrityReport {

    private boolean balanced;
    private BigDecimal totalDebits;
    private BigDecimal totalCredits;
    private BigDecimal netImbalance;
    private long totalLedgerEntries;
    private long totalAccounts;
    private LocalDateTime verifiedAt;

    public LedgerIntegrityReport() {
        this.verifiedAt = LocalDateTime.now();
    }

    public LedgerIntegrityReport(boolean balanced, BigDecimal totalDebits, BigDecimal totalCredits,
                                 BigDecimal netImbalance, long totalLedgerEntries, long totalAccounts) {
        this.balanced = balanced;
        this.totalDebits = totalDebits;
        this.totalCredits = totalCredits;
        this.netImbalance = netImbalance;
        this.totalLedgerEntries = totalLedgerEntries;
        this.totalAccounts = totalAccounts;
        this.verifiedAt = LocalDateTime.now();
    }

    // Getters and Setters
    public boolean isBalanced() {
        return balanced;
    }

    public void setBalanced(boolean balanced) {
        this.balanced = balanced;
    }

    public BigDecimal getTotalDebits() {
        return totalDebits;
    }

    public void setTotalDebits(BigDecimal totalDebits) {
        this.totalDebits = totalDebits;
    }

    public BigDecimal getTotalCredits() {
        return totalCredits;
    }

    public void setTotalCredits(BigDecimal totalCredits) {
        this.totalCredits = totalCredits;
    }

    public BigDecimal getNetImbalance() {
        return netImbalance;
    }

    public void setNetImbalance(BigDecimal netImbalance) {
        this.netImbalance = netImbalance;
    }

    public long getTotalLedgerEntries() {
        return totalLedgerEntries;
    }

    public void setTotalLedgerEntries(long totalLedgerEntries) {
        this.totalLedgerEntries = totalLedgerEntries;
    }

    public long getTotalAccounts() {
        return totalAccounts;
    }

    public void setTotalAccounts(long totalAccounts) {
        this.totalAccounts = totalAccounts;
    }

    public LocalDateTime getVerifiedAt() {
        return verifiedAt;
    }

    public void setVerifiedAt(LocalDateTime verifiedAt) {
        this.verifiedAt = verifiedAt;
    }
}

